import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';

export default function Resources() {
  const { selectedCollege, resources, dark, user } = useApp();
  const css = getTheme(dark);
  const [tab] = useState('note');
  const [search] = useState('');
  const [subject] = useState('all');

  const displayCollege =
    user?.role === 'student' && user?.college
      ? user.college
      : selectedCollege;

  // 🔥 DELETE FUNCTION
  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete?")) return;

    try {
      await fetch(`http://localhost:5000/api/resources/${id}`, {
        method: 'DELETE'
      });

      alert('Deleted successfully');
      window.location.reload(); // simple refresh
    } catch (err) {
      console.error(err);
    }
  };

  const filtered = resources.filter((r) => {
    const matchType = r.type === tab;
    const matchSearch =
      r.title.toLowerCase().includes(search.toLowerCase()) ||
      r.subject.toLowerCase().includes(search.toLowerCase());
    const matchSubject = subject === 'all' || r.subject === subject;

    const matchCollege =
      user?.role === 'student'
        ? true
        : (
            !selectedCollege ||
            r.college === selectedCollege?._id ||
            r.college?._id === selectedCollege?._id
          );

    return matchType && matchCollege && matchSearch && matchSubject;
  });

  return (
    <div className="fade-in">
      <h1>{displayCollege ? displayCollege.short : 'All'} Resources</h1>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
        {filtered.map((r) => (
          <div
            key={r._id}
            style={{
              width: '320px',
              padding: 8,
              border: '1px solid #ccc',
              borderRadius: 8,
              fontSize: 13,
              background: dark ? '#1e293b' : '#fff'
            }}
          >
            <h3 style={{ fontSize: 14 }}>{r.title}</h3>

            <p style={{ margin: '4px 0' }}>
              {r.subject} · {r.uploadedBy?.name || r.uploadedBy}
            </p>

            <p style={{ marginBottom: 6 }}>
              {r.college?.name || r.college}
            </p>

            {/* 🔥 PREVIEW */}
            {r.fileUrl && (
              <div>
                {r.fileUrl.endsWith('.pdf') ? (
                  <iframe
                    src={`http://localhost:5000${r.fileUrl}`}
                    width="100%"
                    height="200px"
                    title="PDF Viewer"
                  />
                ) : (
                  <iframe
                    src={`https://docs.google.com/gview?url=http://localhost:5000${r.fileUrl}&embedded=true`}
                    width="100%"
                    height="200px"
                    title="Doc Viewer"
                  />
                )}
              </div>
            )}

            {/* 🔥 BUTTONS */}
            <div style={{ display: 'flex', gap: 6, marginTop: 6 }}>

              {/* Open */}
              {r.fileUrl && (
                <button
                  onClick={() => window.open(`http://localhost:5000${r.fileUrl}`)}
                  style={{
                    fontSize: 12,
                    padding: '4px 8px',
                    cursor: 'pointer'
                  }}
                >
                  Open
                </button>
              )}

              {/* 🔥 DELETE (only teacher) */}
              {user?.role === 'teacher' && (
                <button
                  onClick={() => handleDelete(r._id)}
                  style={{
                    fontSize: 12,
                    padding: '4px 8px',
                    background: 'red',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 4,
                    cursor: 'pointer'
                  }}
                >
                  Delete
                </button>
              )}

            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
